//! The capability-index skill, generated by `tuff_packs::engine::index`.

use std::path::Path;

use crate::error::Result;
use crate::resolver::Scope;

pub(crate) use tuff_packs::engine::index::CAPABILITY_INDEX_ID;

/// Regenerate the index for `repo_root`, keeping baselines in Tuff's cache.
pub(crate) fn regenerate_capability_index(repo_root: &Path, scope: Scope) -> Result<()> {
    tuff_packs::engine::index::regenerate_capability_index(tuff_packs::engine::Destination {
        root: repo_root,
        scope,
        baselines: &super::baselines()?,
    })
}
